'use client';
import { useCallback, useEffect, useId, useRef, useState } from 'react';
import StoryProgressSegments from '../../../effects/story-progress-segments';
import { meta as storyMeta } from '../../../effects/story-progress-segments/meta';
import type { EffectMeta, ParamValues } from '../../../types';
import { FlagBanner, FlagMark } from './art';
import { CREATORS } from './data';
import { Viewer } from './Viewer';
import styles from './styles.module.css';

const defaults = (m: EffectMeta): ParamValues => Object.fromEntries(m.params.map((p) => [p.key, p.default]));

export default function Stories() {
  const uid = useId();
  const [open, setOpen] = useState<number | null>(null);
  const [seen, setSeen] = useState<Record<string, number>>({});
  const opener = useRef<HTMLElement | null>(null);

  const show = (i: number, el: HTMLElement) => { opener.current = el; setOpen(i); };
  const close = useCallback(() => setOpen(null), []);
  const onSeen = useCallback((id: string, card: number) => setSeen((s) => (s[id] !== undefined && s[id] >= card ? s : { ...s, [id]: card })), []);

  // While the viewer is open: the page behind is inert (below) and does not scroll; focus returns to the ring.
  useEffect(() => {
    if (open === null) return;
    const html = document.documentElement;
    const prev = html.style.overflow;
    html.style.overflow = 'hidden';
    return () => {
      html.style.overflow = prev;
      const el = opener.current;
      if (el?.isConnected) requestAnimationFrame(() => el.focus({ preventScroll: true }));
    };
  }, [open]);

  return (
    <div className={styles.root}>
      <div className={styles.page} inert={open !== null}>
        <header className={styles.masthead}>
          <FlagBanner className={styles.banner} />
          <h2 className={styles.town}>Port Ellery</h2>
          <p className={styles.tagline}>Stories from the harbour, the quay and the people who keep them running.</p>
          <p className={styles.sample}><span className="mk-label">Sample content</span> A fictional town; every account and notice is invented.</p>
        </header>

        <section aria-labelledby={`${uid}-tray`} className={styles.traySection}>
          <div className={styles.trayHead}>
            <h3 id={`${uid}-tray`} className={styles.h3}>Today’s stories</h3>
            <p className={styles.small}>Up for 24 hours, then kept in each account’s archive.</p>
          </div>
          <ul className={styles.tray}>
            {CREATORS.map((c, i) => {
              const watched = seen[c.id] ?? -1;
              const unseen = Math.max(0, c.segments.length - 1 - watched);
              const done = watched >= c.segments.length - 1;
              return (
                <li key={c.id}>
                  <button type="button" className={styles.ring} data-seen={done || undefined} onClick={(e) => show(i, e.currentTarget)}>
                    <span className={styles.ringArt}><FlagMark flag={c.flag} className={styles.ringFlag} /></span>
                    <span className={styles.ringName}>{c.name}</span>
                    <span className={styles.ringState}>{done ? 'Seen' : `${watched < 0 ? c.segments.length : unseen} new`}</span>
                    <span className="mk-sr-only">, {c.ago} ago</span>
                  </button>
                </li>
              );
            })}
          </ul>
        </section>

        <section aria-labelledby={`${uid}-how`} className={styles.how}>
          <h3 id={`${uid}-how`} className={styles.h3}>Every gesture has a button</h3>
          <dl className={styles.legend}>
            <div><dt>Tap the right or left of a card</dt><dd>Next / Previous card buttons, or → and ←</dd></div>
            <div><dt>Press and hold</dt><dd>Pause button, or Space</dd></div>
            <div><dt>Swipe sideways</dt><dd>Account buttons under the reply box, or Shift + → / ←</dd></div>
            <div><dt>Swipe down</dt><dd>Close button, or Esc</dd></div>
          </dl>
          <p className={styles.small}>Cards move on by themselves every six seconds and stop while you hold, reply or switch tabs. With reduced motion they never move on their own.</p>
        </section>

        <section aria-labelledby={`${uid}-embed`} className={styles.embedSection}>
          <div className={styles.embedCopy}>
            <h3 id={`${uid}-embed`} className={styles.h3}>From the harbour newsletter</h3>
            <p className={styles.small}>A story can live outside the tray, too. Tidewater Notes’ low-tide walk is embedded here with its own pause and step controls.</p>
          </div>
          <div className={styles.embed}>
            {/* Its clock stops while the full-screen viewer covers the page. */}
            <StoryProgressSegments params={{ ...defaults(storyMeta), duration: 5000, slides: 5, transition: 'slide', autoAdvance: open === null }} />
          </div>
        </section>

        <footer className={styles.footer}>
          <p>Port Ellery, its harbour office, bakery, lifeboat station, ferry desk and gallery are fictional. Replies in this demo are not sent anywhere.</p>
        </footer>
      </div>

      {open !== null ? <Viewer start={open} onClose={close} onSeen={onSeen} /> : null}
    </div>
  );
}

/**
 * International maritime signal flags (public-domain shapes) used as account marks and as the town's banner,
 * plus the flat drawings behind some story cards. All decorative: callers provide the words.
 */
import type { ReactNode } from 'react';
import type { Flag, Segment } from './data';

const C = { red: '#c8262c', yellow: '#f2c230', blue: '#2456a6', navy: '#1b2a4e', white: '#fbfaf6', black: '#16181d' };

const FLAGS: Record<Flag | 'E' | 'R' | 'Y', ReactNode> = {
  H: <><rect width="15" height="20" fill={C.white} /><rect x="15" width="15" height="20" fill={C.red} /></>,
  B: <path d="M0 0h30l-9 10 9 10H0z" fill={C.red} />,
  L: <><rect width="30" height="20" fill={C.black} /><rect width="15" height="10" fill={C.yellow} /><rect x="15" y="10" width="15" height="10" fill={C.yellow} /></>,
  F: <><rect width="30" height="20" fill={C.white} /><path d="M15 1.500 28 10 15 18.500 2 10z" fill={C.red} /></>,
  G: <>{[0, 1, 2, 3, 4, 5].map((i) => <rect key={i} x={i * 5} width="5" height="20" fill={i % 2 ? C.blue : C.yellow} />)}</>,
  E: <><rect width="30" height="10" fill={C.blue} /><rect y="10" width="30" height="10" fill={C.red} /></>,
  R: <><rect width="30" height="20" fill={C.red} /><rect x="12.500" width="5" height="20" fill={C.yellow} /><rect y="7.500" width="30" height="5" fill={C.yellow} /></>,
  Y: <><rect width="30" height="20" fill={C.yellow} />{[-20, -8, 4, 16, 28].map((x) => <path key={x} d={`M${x} 20 ${x + 20} 0h6L${x + 6} 20z`} fill={C.red} />)}</>,
};

export function FlagMark({ flag, className }: { flag: keyof typeof FLAGS; className?: string }) {
  return (
    <svg viewBox="0 0 30 20" className={className} aria-hidden="true" focusable="false" preserveAspectRatio="xMidYMid meet">
      {FLAGS[flag]}
      {flag === 'H' || flag === 'F' ? <rect x="0.250" y="0.250" width="29.500" height="19.500" fill="none" stroke="#16181d" strokeOpacity="0.25" strokeWidth="0.500" /> : null}
    </svg>
  );
}

/** "ELLERY" spelled in signal flags. */
export function FlagBanner({ className }: { className?: string }) {
  const word = ['E', 'L', 'L', 'E', 'R', 'Y'] as const;
  return (
    <svg viewBox="0 0 204 30" className={className} aria-hidden="true" focusable="false">
      <path d="M0 4.500h204" stroke="currentColor" strokeWidth="1" />
      {word.map((f, i) => (
        <g key={i} transform={`translate(${6 + i * 33} 5)`}>
          <svg width="30" height="20" viewBox="0 0 30 20">{FLAGS[f]}</svg>
        </g>
      ))}
    </svg>
  );
}

/** Flat drawings behind some cards; colours follow the card's field via currentColor. */
export function CardArt({ art }: { art: NonNullable<Segment['art']> }) {
  const common = { fill: 'none', stroke: 'currentColor', strokeWidth: 3, strokeLinecap: 'round' as const, strokeLinejoin: 'round' as const };
  switch (art) {
    case 'tide': return <svg viewBox="0 0 200 100" aria-hidden="true" focusable="false"><path d="M0 80C40 80 60 18 100 18s60 62 100 62" {...common} /><path d="M100 18v-10" {...common} /><circle cx="100" cy="18" r="5" fill="currentColor" /></svg>;
    case 'wind': return <svg viewBox="0 0 200 100" aria-hidden="true" focusable="false"><path d="M40 20l110 60M150 80l-26-2M150 80l-12-23" {...common} strokeWidth={5} /><path d="M40 20l-6 14M52 27l-6 14M64 34l-6 14" {...common} /></svg>;
    case 'bun': return <svg viewBox="0 0 200 100" aria-hidden="true" focusable="false"><path d="M20 84h160" {...common} />{[50, 100, 150].map((x) => <g key={x}><ellipse cx={x} cy={62} rx={22} ry={17} fill="currentColor" /><path d={`M${x - 10} 58c5-5 15-5 20 0`} stroke="#1b2a4e" strokeWidth={2.5} fill="none" strokeLinecap="round" /></g>)}</svg>;
    case 'boat': return <svg viewBox="0 0 200 100" aria-hidden="true" focusable="false"><path d="M20 70c30-10 40 10 80 0s50-10 80 0" {...common} /><path d="M50 60h100l-14 16H66z" fill="currentColor" /><path d="M86 60V36h30l10 24" {...common} /><path d="M100 36V22" {...common} /></svg>;
    case 'ferry': return <svg viewBox="0 0 200 100" aria-hidden="true" focusable="false"><path d="M0 70h40M160 70h40" {...common} strokeWidth={6} /><path d="M60 62h80l-8 12H68z" fill="currentColor" /><path d="M78 62V48h36v14M92 48v-8" {...common} /><path d="M40 82c40 6 80 6 120 0" {...common} strokeDasharray="6 8" /></svg>;
    case 'knot': return <svg viewBox="0 0 200 100" aria-hidden="true" focusable="false"><path d="M30 50c30 0 40-34 70-34s34 34 0 34-40 34-70 34M100 50c30 0 40 34 70 34" {...common} strokeWidth={6} /></svg>;
  }
}

/**
 * Sample content: Port Ellery and every account, notice and number in these stories are fictional.
 * Segments are real text drawn over flat colour fields, so each one has a written equivalent by construction.
 */
export type Flag = 'H' | 'B' | 'L' | 'F' | 'G';
export type Field = 'navy' | 'red' | 'yellow' | 'blue' | 'paper';

export interface Segment {
  id: string;
  field: Field;
  kicker: string;
  big: string;
  body: string;
  /** Optional drawn element behind the type. */
  art?: 'tide' | 'wind' | 'bun' | 'boat' | 'ferry' | 'knot';
  /** What a screen reader hears for the drawing (when there is one). */
  artAlt?: string;
}

export interface Creator { id: string; name: string; flag: Flag; flagName: string; ago: string; iso: string; segments: Segment[] }

