/* Port Ellery stories — "harbour signal flags": flat primary fields (signal red, flag yellow, navy, blue) with
   chunky grotesque numerals, the town spelled in flags, and a viewer that is a dark harbour-night frame. */
.root {
  --pe-navy: #1b2a4e;
  --pe-red: #c8262c;     /* paper text 5.3:1 */
  --pe-yellow: #f2c230;  /* navy text 8.4:1 */
  --pe-blue: #2456a6;    /* paper text 6.8:1 */
  --pe-paper: #fbfaf6;
  --pe-mist: #d5dcec;    /* secondary text on navy, 10.3:1 */
  --pe-accent: #b3202a;  /* small accent text on the page, ≥ 5.29:1 */
  position: relative;
  min-height: 100dvh;
  background: var(--mk-bg);
  color: var(--mk-ink);
  font-family: var(--mk-font-text);
}
:global([data-theme='dark']) .root { --pe-accent: #ff8a80; }
.page { max-width: 760px; margin: 0 auto; padding: 0 16px 56px; }
.small { margin: 0; font-size: 0.8125rem; line-height: 1.5; color: var(--mk-ink-muted); }
.h3 { margin: 0; font-family: var(--mk-font-display); font-size: 1.25rem; font-weight: 700; letter-spacing: -0.015em; }

.masthead { padding: 28px 0 22px; border-bottom: 3px solid var(--mk-ink); }
.banner { display: block; width: min(100%, 288px); height: auto; color: var(--mk-ink-muted); }
.town { margin: 14px 0 0; font-family: var(--mk-font-display); font-size: clamp(3.25rem, 2.2rem + 6cqi, 5.75rem); font-weight: 800; line-height: 0.9; letter-spacing: -0.05em; }
.tagline { margin: 12px 0 0; max-width: 32ch; font-family: var(--mk-font-serif); font-size: 1.375rem; line-height: 1.25; text-wrap: pretty; }
.sample { margin: 14px 0 0; font-size: 0.8125rem; color: var(--mk-ink-muted); }
.sample > :first-child { margin-right: 8px; color: var(--pe-accent); }

.traySection { padding: 22px 0 6px; }
.trayHead { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: baseline; gap: 4px 16px; margin-bottom: 12px; }
.tray { display: flex; gap: 12px; margin: 0 -16px; padding: 6px 16px 14px; overflow-x: auto; overscroll-behavior-x: contain; scroll-snap-type: x proximity; scroll-padding-inline: 16px; list-style: none; scrollbar-width: thin; }
.tray li { flex: none; scroll-snap-align: start; }
/* position: relative keeps the visually-hidden text inside the scroller (an absolute child would escape its clip). */
.ring { position: relative; display: grid; justify-items: center; gap: 4px; width: 88px; padding: 4px 0 6px; border: 0; border-radius: var(--mk-radius-m); background: none; color: inherit; font: inherit; text-align: center; }
.ringArt {
  display: grid; place-items: center; box-sizing: border-box; width: 76px; height: 76px; padding: 3px; border-radius: 50%;
  background: conic-gradient(var(--pe-red) 0 25%, var(--pe-yellow) 0 50%, var(--pe-blue) 0 75%, var(--pe-navy) 0 100%);
}
.ring[data-seen] .ringArt { padding: 1.5px; background: var(--mk-line-strong); }
.ringFlag { box-sizing: border-box; width: 100%; height: 100%; padding: 16px 12px; border: 3px solid var(--mk-bg); border-radius: 50%; background: var(--mk-surface); }
.ring:hover .ringFlag { background: var(--mk-surface-2); }
.ringName { max-width: 88px; font-size: 0.75rem; font-weight: 600; line-height: 1.2; }
.ringState { font-family: var(--mk-font-mono); font-size: 0.625rem; letter-spacing: 0.06em; text-transform: uppercase; color: var(--mk-ink-muted); }
.ring:not([data-seen]) .ringState { color: var(--pe-accent); }

.how { margin-top: 18px; padding: 18px 16px; background: var(--mk-surface); border: 1px solid var(--mk-line); }
.legend { display: grid; margin: 12px 0; }
.legend div { display: grid; gap: 2px; padding: 9px 0; border-top: 1px solid var(--mk-line); }
@container (min-width: 36rem) { .legend div { grid-template-columns: 1fr 1.2fr; gap: 16px; } }
.legend dt { font-size: 0.875rem; font-weight: 600; }
.legend dd { margin: 0; font-size: 0.875rem; color: var(--mk-ink-muted); }

.embedSection { display: grid; gap: 14px; margin-top: 34px; }
/* The composed recipe's signal tone takes the harbour red (and keeps light text on it in both themes). */
.embed { --mk-signal: #c8262c; --mk-on-signal: #fbfaf6; background: var(--mk-surface); border: 1px solid var(--mk-line); }
.footer { margin-top: 40px; padding-top: 14px; border-top: 1px solid var(--mk-line); font-size: 0.8125rem; line-height: 1.5; color: var(--mk-ink-muted); }
.footer p { margin: 0; }

/* ── Viewer ─────────────────────────────────────────────────────────────── */
.viewerLayer { position: absolute; inset: 0; z-index: 40; background: #0c111d; }
.viewerLayer :focus-visible { outline: 2px solid var(--pe-yellow); outline-offset: 2px; }
.viewerPanel { position: sticky; top: 44px; box-sizing: border-box; height: calc(100dvh - 44px); display: grid; justify-items: center; color: var(--pe-paper); }
.sideBtn { display: none; }
@container (min-width: 48rem) {
  .viewerPanel { grid-template-columns: 1fr auto 1fr; align-items: center; padding: 16px 0; }
  .sideBtn { display: grid; place-items: center; width: 52px; height: 52px; padding: 0; border: 1px solid #8c97b5; border-radius: 50%; background: transparent; color: var(--pe-paper); }
  .sideBtn:hover:not(:disabled) { background: rgb(251 250 246 / 0.1); }
  .sideBtn:disabled { color: #59627c; border-color: #3a4560; }
  .sideBtn svg { width: 24px; height: 24px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  .sidePrev { justify-self: end; margin-right: 28px; }
  .sideNext { justify-self: start; margin-left: 28px; }
}
.phone { position: relative; container-type: inline-size; display: flex; flex-direction: column; width: 100%; max-width: 520px; height: 100%; overflow: hidden; background: var(--pe-navy); }
@container (min-width: 48rem) {
  .phone { width: min(440px, calc((100dvh - 76px) * 0.5625)); height: min(calc(100dvh - 76px), 860px); border-radius: 16px; box-shadow: 0 30px 80px rgb(0 0 0 / 0.5); }
}
.top { padding: 10px 12px 6px; background: var(--pe-navy); }
.segments { display: flex; gap: 4px; }
.seg { flex: 1; height: 3px; overflow: hidden; border-radius: 2px; background: #59627c; }
.segFill { display: block; height: 100%; background: var(--pe-paper); transform: scaleX(0); transform-origin: left center; }
.seg[data-state='done'] .segFill { transform: scaleX(1); }
.head { display: flex; align-items: center; gap: 10px; margin-top: 8px; }
.headFlag { flex: none; width: 36px; height: 24px; }
.headName { display: grid; flex: 1; min-width: 0; margin: 0; line-height: 1.25; }
.headName > span:first-child { overflow: hidden; font-size: 0.9375rem; font-weight: 700; white-space: nowrap; text-overflow: ellipsis; }
.headTime { font-size: 0.75rem; color: var(--pe-mist); }
.headBtn { display: grid; place-items: center; flex: none; width: 44px; height: 44px; padding: 0; border: 0; border-radius: 50%; background: transparent; color: var(--pe-paper); }
.headBtn:hover { background: rgb(251 250 246 / 0.12); }
.headBtn[aria-pressed='true'] { background: var(--pe-paper); color: var(--pe-navy); }
.headBtn svg { width: 22px; height: 22px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
.solid { fill: currentColor; stroke: none; }

.stage { position: relative; flex: 1; min-height: 0; overflow: hidden; touch-action: none; user-select: none; -webkit-user-select: none; -webkit-touch-callout: none; }
.card { position: absolute; inset: 0; display: flex; flex-direction: column; padding: 24px 22px 28px; }
.card[data-field='navy'] { background: var(--pe-navy); color: var(--pe-paper); }
.card[data-field='red'] { background: var(--pe-red); color: var(--pe-paper); }
.card[data-field='yellow'] { background: var(--pe-yellow); color: var(--pe-navy); }
.card[data-field='blue'] { background: var(--pe-blue); color: var(--pe-paper); }
.card[data-field='paper'] { background: var(--pe-paper); color: var(--pe-navy); }
.cardBody { display: flex; flex-direction: column; gap: 8px; height: 100%; }
.cardArt { width: 78%; max-width: 300px; margin: 8% auto auto 0; }
.cardArt svg { display: block; width: 100%; height: auto; }
.cardKicker { margin: auto 0 0; font-family: var(--mk-font-mono); font-size: 0.75rem; letter-spacing: 0.1em; text-transform: uppercase; }
.cardArt + .cardKicker { margin-top: 0; }
.cardBig { margin: 0; font-family: var(--mk-font-display); font-size: clamp(2.5rem, 15cqi, 4.5rem); font-weight: 800; line-height: 0.92; letter-spacing: -0.045em; overflow-wrap: anywhere; }
.cardText { max-width: 30ch; margin: 4px 0 0; font-size: 1.0625rem; line-height: 1.45; }
.cardBtn { position: absolute; top: 50%; display: grid; place-items: center; width: 44px; height: 44px; padding: 0; border: 0; border-radius: 50%; background: rgb(12 17 29 / 0.6); color: var(--pe-paper); transform: translateY(-50%); }
.cardBtn svg { width: 22px; height: 22px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
.cardPrev { left: 8px; } .cardNext { right: 8px; }
.endCard { display: grid; justify-items: start; gap: 12px; margin: auto 0; }
.endCard p { margin: 0; max-width: 30ch; font-size: 1.0625rem; line-height: 1.45; }
.endTitle { margin: 0; font-family: var(--mk-font-display); font-size: 2.25rem; font-weight: 800; line-height: 1; letter-spacing: -0.035em; }
.endActions { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 6px; }
.lightBtn { min-height: 44px; padding: 0 18px; border: 1.5px solid currentColor; border-radius: 999px; background: transparent; color: inherit; font: inherit; font-size: 0.9375rem; font-weight: 600; }

.bottom { display: grid; gap: 4px; padding: 10px 12px calc(8px + env(safe-area-inset-bottom, 0px)); background: var(--pe-navy); }
.reply { display: flex; gap: 8px; }
.replyInput { flex: 1; min-width: 0; min-height: 44px; padding: 0 16px; border: 1px solid #8c97b5; border-radius: 999px; background: transparent; color: var(--pe-paper); font: inherit; font-size: 1rem; }
.replyInput::placeholder { color: var(--pe-mist); }
.sendBtn { min-height: 44px; padding: 0 18px; border: 0; border-radius: 999px; background: var(--pe-yellow); color: var(--pe-navy); font: inherit; font-size: 0.9375rem; font-weight: 700; }
.sendBtn:disabled { background: #2c3a5e; color: var(--pe-mist); cursor: not-allowed; }
.sent { min-height: 1.1em; margin: 0; font-size: 0.75rem; color: var(--pe-mist); }
.accounts { display: flex; justify-content: space-between; gap: 8px; }
.accountBtn { max-width: 48%; min-height: 44px; overflow: hidden; padding: 0 8px; border: 0; border-radius: var(--mk-radius-s); background: none; color: var(--pe-paper); font: inherit; font-size: 0.875rem; font-weight: 600; white-space: nowrap; text-overflow: ellipsis; }
.accountBtn:hover:not(:disabled) { background: rgb(251 250 246 / 0.1); }
.accountBtn:disabled { color: #8c97b5; }

'use client';
/**
 * Full-screen stories viewer, contained in the demo (a sticky panel under the gallery bar, never position: fixed).
 *
 * Clock: the current progress segment's WAAPI fill IS the timer (the story-progress-segments recipe's technique) —
 * pausing the animation pauses the story, its finish advances it. It pauses for the Pause button, a held press,
 * reply focus and a hidden tab; under reduced motion there is no clock at all and nothing advances by itself.
 *
 * Every gesture has a twin: tap left/right = Previous/Next card buttons and ←/→; swipe sideways = account buttons
 * and Shift+←/→; swipe down = Close and Esc; hold = Pause and Space.
 */
import { useCallback, useEffect, useLayoutEffect, useRef, useState, type FormEvent, type KeyboardEvent, type PointerEvent } from 'react';
import { duration as D, spring, springToLinear, useStudioMotion } from '../../../motion';
import { CardArt, FlagMark } from './art';
import { CREATORS, SEGMENT_MS } from './data';
import styles from './styles.module.css';

const TAP_MS = 250;
const SETTLE = springToLinear(spring.settle);
type How = 'auto' | 'manual';

export function Viewer({ start, onClose, onSeen }: { start: number; onClose: () => void; onSeen: (creatorId: string, card: number) => void }) {
  const { reduced } = useStudioMotion();
  const auto = !reduced;
  const [ci, setCi] = useState(start);
  const [si, setSi] = useState(0);
  const [epoch, setEpoch] = useState(0); // restarts the current card's clock
  const [paused, setPaused] = useState(false);
  const [holding, setHolding] = useState(false);
  const [typing, setTyping] = useState(false);
  const [hiddenTab, setHiddenTab] = useState(false);
  const [ended, setEnded] = useState(false);
  const [reply, setReply] = useState('');
  const [sent, setSent] = useState('');
  const [say, setSay] = useState('');
  const creator = CREATORS[ci];
  const seg = creator.segments[si];
  const fills = useRef<(HTMLSpanElement | null)[]>([]);
  const clock = useRef<Animation | null>(null);
  const media = useRef<HTMLDivElement>(null);
  const pauseBtn = useRef<HTMLButtonElement>(null);
  const nextBtn = useRef<HTMLButtonElement>(null);
  const endHead = useRef<HTMLHeadingElement>(null);
  const replyField = useRef<HTMLInputElement>(null);
  const drag = useRef<{ id: number; x: number; y: number; t: number; w: number; h: number; mode: 'none' | 'x' | 'y' } | null>(null);
  const enter = useRef<{ dir: 1 | -1 } | null>(null);
  const manual = useRef(false);
  const anims = useRef(new Set<Animation>());
  const running = auto && !ended && !paused && !holding && !typing && !hiddenTab;

  const track = (a: Animation) => { anims.current.add(a); const done = () => anims.current.delete(a); a.finished.then(done, done); return a; };
  useEffect(() => { const set = anims.current; return () => { set.forEach((a) => a.cancel()); set.clear(); }; }, []);

  // ── navigation ──
  const toCreator = useCallback((next: number, dir: 1 | -1, how: How, card = 0) => {
    if (next >= CREATORS.length) { setEnded(true); return; }
    if (next < 0) { setSi(0); setEpoch((e) => e + 1); return; }
    manual.current = how === 'manual';
    enter.current = { dir };
    setEnded(false); setCi(next); setSi(card); setEpoch((e) => e + 1);
  }, []);
  const nextCard = useCallback((how: How) => {
    manual.current = how === 'manual';
    if (si + 1 < creator.segments.length) setSi(si + 1);
    else toCreator(ci + 1, 1, how);
  }, [si, ci, creator.segments.length, toCreator]);
  const prevCard = useCallback(() => {
    manual.current = true;
    if (si > 0) setSi(si - 1);
    else if (ci > 0) toCreator(ci - 1, -1, 'manual', CREATORS[ci - 1].segments.length - 1);
    else setEpoch((e) => e + 1);
  }, [si, ci, toCreator]);
  const nextRef = useRef(nextCard);
  nextRef.current = nextCard;

  // ── the clock ──
  useLayoutEffect(() => {
    clock.current = null;
    const el = fills.current[si];
    if (!auto || ended || !el || typeof el.animate !== 'function') return;
    const a = el.animate([{ transform: 'scaleX(0)' }, { transform: 'scaleX(1)' }], { duration: SEGMENT_MS, easing: 'linear', fill: 'forwards' });
    clock.current = a;
    a.onfinish = () => { if (clock.current === a) nextRef.current('auto'); };
    return () => { a.onfinish = null; a.cancel(); };
  }, [ci, si, epoch, auto, ended]);
  useEffect(() => {
    const a = clock.current;
    if (!a) return;
    if (running) { if (a.playState === 'paused') a.play(); }
    else if (a.playState === 'running') a.pause();
  }, [running, ci, si, epoch]);

  useEffect(() => {
    const on = () => setHiddenTab(document.hidden);
    document.addEventListener('visibilitychange', on);
    return () => document.removeEventListener('visibilitychange', on);
  }, []);
  // Pause is first in the focus order; with no clock (reduced motion) there is nothing to pause, so Next card leads.
  useEffect(() => { (pauseBtn.current ?? nextBtn.current)?.focus({ preventScroll: true }); }, []);
  useEffect(() => { if (ended) endHead.current?.focus(); }, [ended]);

  // Seen state, announcements (manual moves only), and the entrance of a new account's card.
  useEffect(() => {
    if (ended) return;
    onSeen(creator.id, si);
    if (manual.current) setSay(`Card ${si + 1} of ${creator.segments.length} from ${creator.name}, ${creator.ago} ago.`);
    manual.current = false;
  }, [ci, si, ended]); // eslint-disable-line react-hooks/exhaustive-deps
  useLayoutEffect(() => {
    const el = media.current;
    const e = enter.current;
    enter.current = null;
    if (!el) return;
    el.style.transform = '';
    if (!e || typeof el.animate !== 'function') return;
    track(reduced
      ? el.animate([{ opacity: 0.2 }, { opacity: 1 }], { duration: D.fast, easing: 'linear' })
      : el.animate([{ transform: `translateX(${e.dir * 28}%)`, opacity: 0.3 }, { transform: 'none', opacity: 1 }], { duration: D.moderate, easing: 'cubic-bezier(0.16, 1, 0.3, 1)' }));
  }, [ci]); // eslint-disable-line react-hooks/exhaustive-deps

  // ── gestures ──
  const springBack = () => {
    const el = media.current;
    if (!el) return;
    const from = el.style.transform;
    el.style.transform = '';
    if (!from || reduced || typeof el.animate !== 'function') return;
    track(el.animate([{ transform: from }, { transform: 'none' }], { duration: SETTLE.duration, easing: SETTLE.easing }));
  };
  const onPointerDown = (e: PointerEvent<HTMLDivElement>) => {
    if (e.button !== 0 || ended || (e.target as Element).closest('button, input, a')) return;
    const r = e.currentTarget.getBoundingClientRect();
    drag.current = { id: e.pointerId, x: e.clientX, y: e.clientY, t: performance.now(), w: r.width, h: r.height, mode: 'none' };
    e.currentTarget.setPointerCapture?.(e.pointerId);
    setHolding(true);
  };
  const onPointerMove = (e: PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    const el = media.current;
    if (!d || d.id !== e.pointerId || !el) return;
    const dx = e.clientX - d.x, dy = e.clientY - d.y;
    if (d.mode === 'none') {
      if (Math.abs(dx) > 12 && Math.abs(dx) > Math.abs(dy)) d.mode = 'x';
      else if (dy > 12 && dy > Math.abs(dx)) d.mode = 'y';
    }
    // The card follows the finger 1:1 (direct manipulation is kept under reduced motion), with resistance at the ends.
    if (d.mode === 'x') {
      const edge = (dx > 0 && ci === 0) || (dx < 0 && ci === CREATORS.length - 1);
      el.style.transform = `translateX(${edge ? dx * 0.3 : dx}px)`;
    } else if (d.mode === 'y') {
      el.style.transform = `translateY(${Math.max(0, dy)}px) scale(${1 - Math.min(0.12, (dy / d.h) * 0.25)})`;
    }
  };
  const onPointerUp = (e: PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    if (!d || d.id !== e.pointerId) return;
    drag.current = null;
    setHolding(false);
    const dt = Math.max(1, performance.now() - d.t);
    const dx = e.clientX - d.x, dy = e.clientY - d.y;
    if (d.mode === 'x') {
      const go = Math.abs(dx) > d.w * 0.3 || Math.abs(dx / dt) > 0.5;
      if (go && dx < 0 && ci < CREATORS.length - 1) toCreator(ci + 1, 1, 'manual');
      else if (go && dx > 0 && ci > 0) toCreator(ci - 1, -1, 'manual');
      else springBack();
      return;
    }
    if (d.mode === 'y') { if (dy > d.h * 0.22 || dy / dt > 0.5) onClose(); else springBack(); return; }
    if (dt < TAP_MS) {
      const r = e.currentTarget.getBoundingClientRect();
      const x = e.clientX - r.left;
      const rtl = getComputedStyle(e.currentTarget).direction === 'rtl';
      const back = rtl ? x > r.width * 0.7 : x < r.width * 0.3;
      if (back) prevCard(); else nextCard('manual');
    }
  };
  const onPointerCancel = () => { drag.current = null; setHolding(false); springBack(); };

  const onKey = (e: KeyboardEvent<HTMLDivElement>) => {
    const t = e.target as HTMLElement;
    if (e.key === 'Escape') { e.preventDefault(); onClose(); return; }
    if (t.closest('input, textarea')) return;
    if (e.key === 'ArrowRight') { e.preventDefault(); if (e.shiftKey) toCreator(ci + 1, 1, 'manual'); else if (!ended) nextCard('manual'); }
    else if (e.key === 'ArrowLeft') { e.preventDefault(); if (ended) { setEnded(false); return; } if (e.shiftKey) toCreator(ci - 1, -1, 'manual'); else prevCard(); }
    else if (e.key === ' ' && !t.closest('button, a')) { e.preventDefault(); setPaused((p) => !p); }
  };

  const send = (e: FormEvent) => {
    e.preventDefault();
    const text = reply.trim();
    if (!text) return;
    setReply('');
    setSent(`Sent privately to ${creator.name}. Demo: nothing leaves this page.`);
    replyField.current?.focus(); // Send disables once the field is empty; keep focus in the viewer
  };

  // Esc closes even if focus has fallen out of the dialog (e.g. onto <body> after a control was disabled).
  const closeRef = useRef(onClose);
  closeRef.current = onClose;
  useEffect(() => {
    const onDocKey = (e: globalThis.KeyboardEvent) => { if (e.key === 'Escape' && !e.defaultPrevented) closeRef.current(); };
    document.addEventListener('keydown', onDocKey);
    return () => document.removeEventListener('keydown', onDocKey);
  }, []);

  const prevName = ci > 0 ? CREATORS[ci - 1].name : null;
  const nextName = ci < CREATORS.length - 1 ? CREATORS[ci + 1].name : null;
  const state = ended ? 'End of stories' : !auto ? 'Moves only when you tap' : paused ? 'Paused' : holding ? 'Held' : typing ? 'Paused while you reply' : 'Playing';

  return (
    <div className={styles.viewerLayer}>
      <div className={styles.viewerPanel} role="dialog" aria-modal="true" aria-label={`Stories from Port Ellery — ${creator.name}`} onKeyDown={onKey}>
        <button type="button" className={`${styles.sideBtn} ${styles.sidePrev}`} onClick={() => toCreator(ci - 1, -1, 'manual')} disabled={!prevName}>
          <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M15 5l-7 7 7 7" /></svg>
          <span className="mk-sr-only">Previous account{prevName ? `: ${prevName}` : ''}</span>
        </button>
        <div className={styles.phone}>
          <div className={styles.top}>
            <div className={styles.segments} aria-hidden="true">
              {creator.segments.map((s, i) => (
                <span key={s.id} className={styles.seg} data-state={ended || i < si ? 'done' : i === si ? (auto ? 'current' : 'done') : 'next'}>
                  <span ref={(el) => { fills.current[i] = el; }} className={styles.segFill} />
                </span>
              ))}
            </div>
            <div className={styles.head}>
              <FlagMark flag={creator.flag} className={styles.headFlag} />
              <p className={styles.headName}><span>{creator.name}</span><span className={styles.headTime}><time dateTime={creator.iso}>{creator.ago}</time> · {state}</span></p>
              {auto ? (
                <button ref={pauseBtn} type="button" className={styles.headBtn} aria-pressed={paused} onClick={() => setPaused((p) => !p)} disabled={ended}>
                  {paused
                    ? <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M8 5.500v13l10-6.500z" className={styles.solid} /></svg>
                    : <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M9 6v12M15 6v12" /></svg>}
                  <span className="mk-sr-only">Pause stories</span>
                </button>
              ) : null}
              <button type="button" className={styles.headBtn} onClick={onClose}>
                <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M6 6l12 12M18 6 6 18" /></svg>
                <span className="mk-sr-only">Close stories</span>
              </button>
            </div>
          </div>

          <div className={styles.stage} onPointerDown={onPointerDown} onPointerMove={onPointerMove} onPointerUp={onPointerUp} onPointerCancel={onPointerCancel}>
            <div ref={media} className={styles.card} data-field={seg.field}>
              {ended ? (
                <div className={styles.endCard}>
                  <h2 ref={endHead} tabIndex={-1} className={styles.endTitle}>You’re all caught up</h2>
                  <p>That’s every story Port Ellery posted in the last 24 hours. Nothing plays after this.</p>
                  <div className={styles.endActions}>
                    <button type="button" className={styles.lightBtn} onClick={() => { setEnded(false); toCreator(0, 1, 'manual'); }}>Watch again</button>
                    <button type="button" className={styles.lightBtn} onClick={onClose}>Close</button>
                  </div>
                </div>
              ) : (
                <section key={seg.id} className={styles.cardBody} role="group" aria-roledescription="story card"
                  aria-label={`Card ${si + 1} of ${creator.segments.length} from ${creator.name}, ${creator.ago} ago`}>
                  {seg.art ? <div className={styles.cardArt} role="img" aria-label={seg.artAlt}><CardArt art={seg.art} /></div> : null}
                  <p className={styles.cardKicker}>{seg.kicker}</p>
                  <p className={styles.cardBig}>{seg.big}</p>
                  <p className={styles.cardText}>{seg.body}</p>
                </section>
              )}
            </div>
            {ended ? null : (
              <>
                <button type="button" className={`${styles.cardBtn} ${styles.cardPrev}`} onClick={prevCard}>
                  <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M15 5l-7 7 7 7" /></svg><span className="mk-sr-only">Previous card</span>
                </button>
                <button ref={nextBtn} type="button" className={`${styles.cardBtn} ${styles.cardNext}`} onClick={() => nextCard('manual')}>
                  <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M9 5l7 7-7 7" /></svg><span className="mk-sr-only">Next card</span>
                </button>
              </>
            )}
          </div>

          <div className={styles.bottom}>
            {ended ? null : (
              <form className={styles.reply} onSubmit={send}>
                <label htmlFor="pe-reply" className="mk-sr-only">Reply privately to {creator.name}</label>
                <input ref={replyField} id="pe-reply" className={styles.replyInput} value={reply} placeholder={`Reply to ${creator.name}…`} autoComplete="off"
                  onChange={(e) => setReply(e.target.value)} onFocus={() => setTyping(true)} onBlur={() => setTyping(false)} />
                <button type="submit" className={styles.sendBtn} disabled={!reply.trim()}>Send</button>
              </form>
            )}
            <p className={styles.sent} aria-live="polite">{sent}</p>
            <div className={styles.accounts}>
              <button type="button" className={styles.accountBtn} onClick={() => toCreator(ci - 1, -1, 'manual')} disabled={!prevName}>
                <span aria-hidden="true">‹</span> {prevName ?? 'First account'}
              </button>
              <button type="button" className={styles.accountBtn} onClick={() => toCreator(ci + 1, 1, 'manual')}>
                {nextName ?? 'Finish'} <span aria-hidden="true">›</span>
              </button>
            </div>
          </div>
        </div>
        <button type="button" className={`${styles.sideBtn} ${styles.sideNext}`} onClick={() => toCreator(ci + 1, 1, 'manual')}>
          <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M9 5l7 7-7 7" /></svg>
          <span className="mk-sr-only">{nextName ? `Next account: ${nextName}` : 'Finish stories'}</span>
        </button>
        <p className="mk-sr-only" aria-live="polite">{say}</p>
      </div>
    </div>
  );
}
